  it("keeps authored order when batch keys are equal", () => {
    const queue = new RenderQueue();
    queue.push(rect({ sourceNodeId: "a", sequence: 0, fill: 1 }));
    queue.push(rect({ sourceNodeId: "b", sequence: 1, fill: 2 }));
