    const nodes = Array.from(
      { length: 4 },
      (_, index) => new HudNode({ id: `i${index}`, width: 16, height: 16 }),
    );
    const first = layoutGrid(nodes, {
      columns: 2,
      rows: 2,
      cellWidth: 16,
      cellHeight: 16,
      gapX: 0,
      gapY: 0,
    });
    const second = layoutGrid(nodes, {
