      autoClear: false,
      getScissor: (target: OverlayVec4Target) => {
        target.x = scissor.x;
        target.y = scissor.y;
        target.z = scissor.z;
        target.w = scissor.w;
        return target;
      },
      setScissor: (x: number, y: number, width: number, height: number) => {
        scissor.x = x;
        scissor.y = y;
        scissor.z = width;
        scissor.w = height;
      },
      getScissorTest: () => true,
      setScissorTest() {},
      getViewport: (target: OverlayVec4Target) => {
        target.x = 0;
