      ),
    ).toThrow(HudError);
    const webgl = createWindfoilTextBackend({
      capability: {
        supported: false,
        status: "unsupported",
        reasons: [{ code: "WINDFOIL_WEBGL2_FALLBACK", message: "WebGL2" }],
      },
    });
    expect(webgl.nativeWebgpu).toBe(false);
    expect(webgl.capabilities.rendererKinds).toEqual(["webgpu"]);
  });
})

